def calculate_b_squared(a):
    if a == 2:
        return None
    # b^2 = a^2 - 1 - 2/(a-2)
    b_squared = a**2 - 1 - (2 / (a - 2))
    return b_squared

test_a = [-2, -3, 5, -4]
results = {}
for a in test_a:
    b2 = calculate_b_squared(a)
    if b2 is not None:
        results[a] = b2

print("Calculated b^2 for integer a values:")
for a, b2 in results.items():
    print(f"a = {a}: b^2 = {b2}")

